# Feishu Plugin Changelog Processing

## Changelog Parsing

```python
import re

def parse_changelog(changelog_text):
    pattern = r'### v([\d.]+)\s*\n(.*?)(?=### v|$)'
    matches = re.findall(pattern, changelog_text, re.DOTALL)

    versions = []
    for version, content in matches:
        features = re.findall(r'- \[NEW\] (.+)', content)
        fixes = re.findall(r'- \[FIX\] (.+)', content)
        improvements = re.findall(r'- \[IMP\] (.+)', content)

        versions.append({
            'version': version,
            'features': features,
            'fixes': fixes,
            'improvements': improvements
        })

    return versions
```

## Notification Generation

```python
def generate_notification(version_info):
    message = f"🎉 飞书插件 v{version_info['version']} 更新\n\n"

    if version_info['features']:
        message += "✨ 新功能:\n"
        for f in version_info['features']:
            message += f"• {f}\n"

    if version_info['improvements']:
        message += "\n🚀 改进:\n"
        for i in version_info['improvements']:
            message += f"• {i}\n"

    if version_info['fixes']:
        message += "\n🐛 修复:\n"
        for f in version_info['fixes']:
            message += f"• {f}\n"

    return message
```

